export function InlineStoreDemo() {
    const [items, setItems] = useState([]);
    const [totalPrice, setTotalPrice] = useState(0.0);
    const [log, setLog] = useState("");
    const itemCount = useMemo(() => {
        return items.length;
    }, [items]);
    const summary = useMemo(() => {
        return items.length === 0 ? "cart empty" : "total: " + items.length.toString() + " items";
    }, [items]);
    const addApple = () => {
            CartStore.addItem("Apple", 5.0);
            setLog("Added: Apple ¥5.0");
    };
    const addBook = () => {
            CartStore.addItem("OmniView Guide", 39.9);
            setLog("Added: OmniView Guide ¥39.9");
    };
    const addLaptop = () => {
            CartStore.addItem("Laptop", 5999.0);
            setLog("Added: Laptop ¥5999.0");
    };
    const remove = () => {
            CartStore.removeLast();
            setLog("Removed last item");
    };
    const clearCart = () => {
            CartStore.clear();
            setLog("Cart cleared");
    };
    const addItem = (name, price) => {
            setItems(prev => [...prev, name]);
            setTotalPrice(totalPrice + price);
    };
    const removeLast = () => {
            if (items.length > 0) {
                // TODO: mutation operation 'pop' on items
                setTotalPrice(totalPrice - 10.0);
            }
    };
    const clear = () => {
            setItems([]);
            setTotalPrice(0.0);
    };


    return (
        <div
            className={styles['container']}
        >
            <h3>
                {'Inline Store Demo'}
            </h3>
            <p>
                {'Items:'}
                {itemCount}
            </p>
            <p>
                {'Summary:'}
                {summary}
            </p>
            <p>
                {'Total:'}
                {totalPrice}
            </p>
            <button
                onClick={(e) => { addApple({}) }}
            >
                {'Add Apple'}
            </button>
            <button
                onClick={(e) => { remove({}) }}
            >
                {'Remove'}
            </button>
            <p>
                {log}
            </p>
        </div>
    );
}

